/*
 * A389735  Standard composition numbers of integer compositions that do not
 *          comprise a finite arithmetic progression.
 * https://oeis.org/A389735
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n‑th integer k such that the standard composition of
 *            k (A066099) is NOT an arithmetic progression. The sequence is
 *            generated by enumerating k≥1, computing the composition,
 *            checking if it fails to be an AP, and collecting those k’s in
 *            order
 * Range:     u8 n <= 65, u16 n <= 65, u32 n <= 65, u64 n <= 65, u128 n <= 65,
 *            big any n
 * Helpers:   is_non_ap
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/is_non_ap.h"

/* Cache of discovered terms */
static seq_t *cache = NULL;
static idx_t cache_len = 0;   /* number of cached terms */
static idx_t cache_cap = 0;   /* allocated capacity of cache array */
static idx_t last_k   = 0;    /* last integer k processed */

/* Required function */
seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* undefined index – safe return */

    /* Ensure the cache has at least n terms */
    if (n > cache_len) {
        /* grow capacity if needed */
        if (cache_cap < n) {
            idx_t new_cap = cache_cap ? cache_cap << 1 : 64;
            if (new_cap < n) new_cap = n;
            seq_t *tmp = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
            cache = tmp;
            cache_cap = new_cap;
        }

        /* enumerate k's from where we left off */
        idx_t k = last_k + 1;
        while (cache_len < n) {
            if (is_non_ap(k)) {
                cache[cache_len++] = (seq_t)k;
            }
            ++k;
        }
        last_k = k - 1;
    }

    return cache[n - 1];
}
